// Fixture identity constants (no-coincidence discipline: independent of
// every other qa fixture's names). Both libraries' episodes are 120 s lavfi
// files, so the completion floor (watchedDurationFloor 0.9 × 120 = 108)
// sits ABOVE every matrix staging position (3, 7, 11 — no accidental
// completions) and BELOW the chain joint's completion PUT (120 — completes).
const (
	qaAcctChainDirA = "QA Acct Chain Alpha S01"
	qaAcctChainEp1  = qaAcctChainDirA + "/QA Acct Chain Alpha S01E01.mkv"
	qaAcctChainEp2  = qaAcctChainDirA + "/QA Acct Chain Alpha S01E02.mkv"
	qaAcctChainDirB = "QA Acct Chain Bravo S01"
	qaAcctChainEpB  = qaAcctChainDirB + "/QA Acct Chain Bravo S01E01.mkv"

	qaAcctMatrixDirA = "QA Acct Matrix Alpha S01"
	qaAcctMatrixEpA  = qaAcctMatrixDirA + "/QA Acct Matrix Alpha S01E01.mkv"
	qaAcctMatrixDirB = "QA Acct Matrix Bravo S01"
	qaAcctMatrixEpB  = qaAcctMatrixDirB + "/QA Acct Matrix Bravo S01E01.mkv"

	qaAcctMediaDuration = "120" // seconds — the probeable duration both tests' floors key on

	qaAcctUsername    = "qa-acct-user"
	qaAcctPassword    = "qa-acct-passphrase-1"
	qaAcctGroupName   = "QA Acct Grants"
	qaAcctAdminChain  = "qa-acct-chain-admin-token"
	qaAcctAdminMatrix = "qa-acct-matrix-admin-token"

	// The staged ledger positions (the slot discriminators): slot 0's rows
	// read 7/11, the user's own row reads 3.
	qaAcctPosA0   = int64(7)
	qaAcctPosB0   = int64(11)
	qaAcctPosUser = int64(3)
)

// qaAcctMedia generates a tiny-resolution 120 s mkv (ultrafast: ~0.5 s per
// file; the probe reads 120.0 exactly, pinning the completion floor at 108).
func qaAcctMedia(t *testing.T, path string) {
	t.Helper()
	mustMkdir(t, filepath.Dir(path))
	if err := exec.Command("ffmpeg",
		"-f", "lavfi",
		"-i", "testsrc=duration="+qaAcctMediaDuration+":size=16x16:rate=10",
		"-loglevel", "error",
		"-preset", "ultrafast",
		"-y",
		filepath.Clean(path),
	).Run(); err != nil {
		t.Fatalf("ffmpeg generate %s: %v", filepath.Base(path), err)
	}
}

// qaAcctJoint is one composed accounts joint: the real server subprocess +
// the two serial libraries (A = the grant target, B = the hidden one).
type qaAcctJoint struct {
	srv    qaSerialServer
	client *http.Client
	admin  string
	libA   int64
	libB   int64
}

// qaAcctStartJoint boots the joint: the seven server-side binaries + the
// shikimori plugin (upstream pinned to a local all-404 stub — no assertion
// here needs enrichment), the REAL cmd/mellifera subprocess, and the two
// serial libraries. The scan stays with the caller.
func qaAcctStartJoint(t *testing.T, adminToken, nameA, nameB, rootA, rootB string) *qaAcctJoint {
	t.Helper()
	// The all-404 upstream: derive attempts fail log-and-skip; scan status
	// (what settle waits on) never depends on enrichment.
	up := httptest.NewServer(http.NotFoundHandler())
	t.Cleanup(up.Close)
	tmp := t.TempDir()
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-acct-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-acct-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-acct-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-acct-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-acct-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-acct-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-acct-grabber", "./plugins/frame-grabber"),
	}, up.URL, tmp, adminToken)
	j := &qaAcctJoint{
		srv:    srv,
		client: &http.Client{Timeout: httpTimeout},
		admin:  adminToken,
	}
	j.libA = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.admin, rootA, nameA)
	j.libB = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.admin, rootB, nameB)
	return j
}

// ---- staging through the REAL admin surface -----------------------------------

// qaAcctCreateUser POSTs /admin/users and returns the created id.
func qaAcctCreateUser(t *testing.T, j *qaAcctJoint, username string) int64 {
	t.Helper()
	var resp struct {
		ID int64 `json:"id"`
	}
	status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/admin/users", j.admin,
		map[string]string{"username": username, "password": qaAcctPassword}, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create user %s: HTTP %d, want 201", username, status)
	}
	if resp.ID == 0 {
		t.Fatalf("create user %s: zero id served", username)
	}
	return resp.ID
}

