// qaAcctPairDevice walks the REAL pairing wire (unauthenticated POST /pair →
// admin approve → the device's single-ride pickup) and returns the raw
// device token and its pairing code (the code is how the admin list
// disambiguates the device row for the bind).
func qaAcctPairDevice(t *testing.T, j *qaAcctJoint) (token, code string) {
	t.Helper()
	var created struct {
		PairingID string `json:"pairing_id"`
		Code      string `json:"code"`
	}
	if status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/pair", "",
		nil, &created); status != http.StatusOK {
		t.Fatalf("POST /pair: HTTP %d, want 200", status)
	}
	if created.PairingID == "" || created.Code == "" {
		t.Fatalf("POST /pair body missing pairing_id/code: %+v", created)
	}
	if status := doRequest(t, j.client, http.MethodPost,
		j.srv.baseURL+"/api/v1/admin/pairings/"+created.PairingID+"/approve", j.admin,
		nil, nil); status != http.StatusOK {
		t.Fatalf("approve pairing %s: HTTP %d, want 200", created.PairingID, status)
	}
	var pickup struct {
		Status      string `json:"status"`
		DeviceToken string `json:"device_token"`
	}
	if status := doRequest(t, j.client, http.MethodGet,
		j.srv.baseURL+"/api/v1/pair/"+created.PairingID+"/wait", "", nil, &pickup); status != http.StatusOK {
		t.Fatalf("pickup pairing %s: HTTP %d, want 200", created.PairingID, status)
	}
	if pickup.Status != "approved" || pickup.DeviceToken == "" {
		t.Fatalf("pickup = %+v, want {status approved, device_token non-empty}", pickup)
	}
	return pickup.DeviceToken, created.Code
}

// qaAcctBindDevice binds the device whose pairing code is code to userID
// through the REAL 9.3 surface (PUT /admin/devices/{id}/user → 204); the
// {id} is the credentials rowid the device list shows, matched by code.
func qaAcctBindDevice(t *testing.T, j *qaAcctJoint, code string, userID int64) {
	t.Helper()
	var list struct {
		Devices []struct {
			DeviceID string `json:"device_id"`
			Code     string `json:"code"`
		} `json:"devices"`
	}
	if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/admin/devices",
		j.admin, nil, &list); status != http.StatusOK {
		t.Fatalf("GET /admin/devices: HTTP %d, want 200", status)
	}
	id := ""
	for _, d := range list.Devices {
		if d.Code == code {
			id = d.DeviceID
			break
		}
	}
	if id == "" {
		t.Fatalf("device with pairing code %s not in the registry (%+v)", code, list.Devices)
	}
	url := j.srv.baseURL + "/api/v1/admin/devices/" + id + "/user"
	if status := doRequest(t, j.client, http.MethodPut, url, j.admin,
		map[string]int64{"user_id": userID}, nil); status != http.StatusNoContent {
		t.Fatalf("bind device %s to user %d: HTTP %d, want 204", id, userID, status)
	}
}

// qaAcctPutProgress PUTs one progress position as token, returning the
// status (the callers assert their own law per call).
func qaAcctPutProgress(t *testing.T, j *qaAcctJoint, token, itemID string, pos int64) int {
	t.Helper()
	return doRequest(t, j.client, http.MethodPut, j.srv.baseURL+"/api/v1/progress/"+itemID, token,
		map[string]int64{"position_seconds": pos}, nil)
}

// ---- the DIRECT ledger read (the provenance oracle — never the wire) -----------

// qaAcctOpenLedger opens the SERVER's SQLite file read-only from the test
// process (WAL allows the concurrent reader; busy_timeout absorbs the
// writer's locks). This is the store-side oracle: a row's (user_id, item_id)
// slot read straight off the table, with no handler between.
func qaAcctOpenLedger(t *testing.T, j *qaAcctJoint) *sql.DB {
	t.Helper()
	dsn := "file:" + filepath.Join(j.srv.dataDir, "mellifera.db") + "?mode=ro&_pragma=busy_timeout(5000)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		t.Fatalf("open ledger read-only: %v", err)
	}
	t.Cleanup(func() { _ = db.Close() })
	return db
}

// qaAcctWatchedSlots returns every user_id holding a watched_items row for
// itemID (the completion ledger's slot stock), sorted ascending.
func qaAcctWatchedSlots(t *testing.T, db *sql.DB, itemID string) []int64 {
	t.Helper()
	rows, err := db.Query("SELECT user_id FROM watched_items WHERE item_id = ?", itemID)
	if err != nil {
		t.Fatalf("read watched slots for %s: %v", itemID, err)
	}
	defer rows.Close()
	out := []int64{}
	for rows.Next() {
		var uid int64
		if err := rows.Scan(&uid); err != nil {
			t.Fatalf("scan watched slot for %s: %v", itemID, err)
		}
		out = append(out, uid)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("read watched slots for %s: %v", itemID, err)
	}
	for i := 1; i < len(out); i++ { // rowid order is not slot order — sort for assertions
		for k := i; k > 0 && out[k] < out[k-1]; k-- {
			out[k], out[k-1] = out[k-1], out[k]
		}
	}
	return out
}

// qaAcctProgressSlots returns the (user_id → position) map of EVERY
// playback_progress row for itemID, across all slots.
func qaAcctProgressSlots(t *testing.T, db *sql.DB, itemID string) map[int64]int64 {
	t.Helper()
	rows, err := db.Query(
		"SELECT user_id, position_seconds FROM playback_progress WHERE item_id = ?", itemID)
	if err != nil {
		t.Fatalf("read progress slots for %s: %v", itemID, err)
	}
	defer rows.Close()
	out := map[int64]int64{}
	for rows.Next() {
		var uid, pos int64
		if err := rows.Scan(&uid, &pos); err != nil {
			t.Fatalf("scan progress slot for %s: %v", itemID, err)
		}
		out[uid] = pos
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("read progress slots for %s: %v", itemID, err)
	}
	return out
}

// qaAcctRequireSlots fails with a full dump unless got is EXACTLY want (the
// empty case passes no variadic args).
func qaAcctRequireSlots(t *testing.T, what, itemID string, got []int64, want ...int64) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: item %s watched slots = %v, want exactly %v", what, itemID, got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s: item %s watched slots = %v, want exactly %v", what, itemID, got, want)
		}
	}
}

// qaAcctAnyOrError decodes EITHER wire shape of every surface the matrix
// reads: the library detail's bare id, the item/series envelope, the
// progress record, or the canonical error body — one decode per row.
type qaAcctAnyOrError struct {
	ID              int64  `json:"id"`
	ItemID          string `json:"item_id"`
	PositionSeconds int64  `json:"position_seconds"`
	Item            struct {
		ID           string `json:"id"`
		RelativePath string `json:"relative_path"`
	} `json:"item"`
	Series struct {
		ID           string `json:"id"`
		RelativePath string `json:"relative_path"`
	} `json:"series"`
	Error struct {
		Code string `json:"code"`
	} `json:"error"`
}

// qaAcctLibIDs lists the libraries' id SET as token (order-independent).
func qaAcctLibIDs(t *testing.T, j *qaAcctJoint, token string) map[int64]bool {
	t.Helper()
	var libs struct {
		Items []struct {
			ID int64 `json:"id"`
		} `json:"items"`
	}
	if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/libraries", token, nil, &libs); status != http.StatusOK {
		t.Fatalf("GET /libraries: HTTP %d, want 200", status)
	}
	out := map[int64]bool{}
	for _, l := range libs.Items {
		out[l.ID] = true
	}
	return out
}

// TestAccountsAuthChainJoint is the l6-accounts 11.3 PROVENANCE joint (spec
// scenarios "Successful login mints a session", "The union of groups is the
// visible set", "An invisible item answers unknown", "The detector fires
// beside the re-grab and is nil-safe", "The write lands in the caller's own
// slot"): one REAL server, one login-minted session, and the DIRECT ledger
// read proving the 5.3 ctx-carried viewer survived
// middleware → viewerFor → identity.ResolveViewer → handler → ctx →
// detector → store write.
func TestAccountsAuthChainJoint(t *testing.T) {
	if testing.Short() {
		t.Skip("QA accounts auth-chain joint: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA accounts auth-chain joint needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	rootA := t.TempDir()
	qaAcctMedia(t, filepath.Join(rootA, qaAcctChainEp1))
	qaAcctMedia(t, filepath.Join(rootA, qaAcctChainEp2))
	rootB := t.TempDir()
	qaAcctMedia(t, filepath.Join(rootB, qaAcctChainEpB))

	j := qaAcctStartJoint(t, qaAcctAdminChain, "QA Acct Chain Alpha", "QA Acct Chain Bravo", rootA, rootB)
	for _, lib := range []int64{j.libA, j.libB} {
		if res := scanLibrary(t, j.client, j.srv.baseURL, j.admin, lib); res.Discovered != res.Persisted {
			t.Fatalf("scan lib %d: discovered=%d persisted=%d; warnings=%v", lib, res.Discovered, res.Persisted, res.Warnings)
		}
	}
	qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.admin, j.libA, j.libB)

	// Ground the entity ids as the env-admin (the fixture's read-back).
	findByRel := func(lib int64, rel string) string {
		for _, it := range listItems(t, j.client, j.srv.baseURL, j.admin, lib) {
			if it.RelativePath == rel {
				return it.ID
			}
		}
		t.Fatalf("item %q missing from lib %d", rel, lib)
		return ""
	}
	ep1 := findByRel(j.libA, qaAcctChainEp1) // the ≥90% completion target
	ep2 := findByRel(j.libA, qaAcctChainEp2) // the plain (sub-threshold) write target
	epB := findByRel(j.libB, qaAcctChainEpB) // the hidden-library write target
	if ep1 == "" || ep2 == "" || epB == "" {
		t.Fatalf("fixture grounding failed: ep1=%q ep2=%q epB=%q", ep1, ep2, epB)
	}
	db := qaAcctOpenLedger(t, j)

	// SLOT-INDEPENDENCE STAGE (zero-user mode: the admin rides legacy slot 0
	// byte-identically): a sub-threshold write into slot 0 — no completion
	// fires, and the row is the slot-0 baseline the user's later writes must
	// not disturb.
	if status := qaAcctPutProgress(t, j, j.admin, ep1, 5); status != http.StatusOK {
		t.Fatalf("admin stage PUT ep1 pos=5: HTTP %d, want 200", status)
	}
	if got := qaAcctProgressSlots(t, db, ep1); len(got) != 1 || got[0] != 5 {
		t.Fatalf("after admin stage: ep1 progress slots = %v, want exactly {0:5}", got)
	}
	qaAcctRequireSlots(t, "sub-threshold stage (no completion)", ep1, qaAcctWatchedSlots(t, db, ep1)) // want NONE

	// THE AUTH CHAIN SETUP — real users/groups/grants/login:
	userID := qaAcctCreateUser(t, j, qaAcctUsername)
	group := qaAcctCreateGroup(t, j, qaAcctGroupName)
	qaAcctAddMember(t, j, group, qaAcctUsername)
	qaAcctGrantCollection(t, j, group, j.libA) // libA ONLY — libB stays ungranted
	bearer := qaAcctLogin(t, j, qaAcctUsername)

	// CHAIN LEGS 1-3 ON THE WIRE — session → VerifySession → ResolveViewer →
	// visibleWhere: the bearer's library listing carries exactly the grant
	// union {A}, and the ungranted library answers 404 like an absent one
	// (hidden ≡ unknown — never 403, never an existence signal).
	gotLibs := qaAcctLibIDs(t, j, bearer)
	if len(gotLibs) != 1 || !gotLibs[j.libA] {
		t.Fatalf("session library set = %v, want exactly {libA=%d} (the grant union)", gotLibs, j.libA)
	}
	var libBResp qaAcctAnyOrError
	if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/libraries/"+strconv.FormatInt(j.libB, 10), bearer, nil, &libBResp); status != http.StatusNotFound {
		t.Fatalf("GET hidden library %d as session: HTTP %d, want 404", j.libB, status)
	}
	if libBResp.Error.Code != "not_found" {
		t.Fatalf("hidden library error code = %q, want not_found", libBResp.Error.Code)
	}

	// CHAIN LEGS 4-8 — THE ≥90% PUT THROUGH THE COMPLETION DETECTOR: the
	// handler resolves the caller's Viewer (viewerFor → ResolveViewer),
	// upserts the progress row into THAT user's slot, then fires the REAL
	// OnProgress fan-out with the stashed context — the detector's
	// access.FromContext reads the writing viewer and stamps the watched row
	// with ITS UserID. The PUT's 200 body is the wire half; the DIRECT store
	// read below is the slot half.
	var putResp qaAcctAnyOrError
	if status := doRequest(t, j.client, http.MethodPut, j.srv.baseURL+"/api/v1/progress/"+ep1, bearer,
		map[string]int64{"position_seconds": 120}, &putResp); status != http.StatusOK { // 120 ≥ 0.9×120 — completes
		t.Fatalf("session ≥90%% PUT ep1: HTTP %d, want 200", status)
	}
	if putResp.ItemID != ep1 || putResp.PositionSeconds != 120 {
		t.Fatalf("≥90%% PUT body = {item:%q pos:%d}, want {ep1, 120}", putResp.ItemID, putResp.PositionSeconds)
	}
	// THE PROVENANCE ORACLE: the watched row sits under userID — and under
	// NOTHING else. A dropped link anywhere in the chain would have handed
	// the detector a bare ctx, whose zero-Viewer UserID 0 lands the row in
	// the legacy slot: slot 0's ABSENCE is what pins every link at once.
	qaAcctRequireSlots(t, "≥90% PUT completion", ep1, qaAcctWatchedSlots(t, db, ep1), userID)
	if got := qaAcctProgressSlots(t, db, ep1); len(got) != 2 || got[userID] != 120 || got[0] != 5 {
		t.Fatalf("after ≥90%% PUT: ep1 progress slots = %v, want exactly {0:5, user %d:120} (the write lands in the caller's slot; slot 0 untouched)", got, userID)
	}

	// THE PLAIN WRITE — sub-threshold, same chain, same slot: progress
	// upserts under userID, and the detector (floor 108) inserts NOTHING.
	if status := qaAcctPutProgress(t, j, bearer, ep2, 30); status != http.StatusOK {
		t.Fatalf("session plain PUT ep2 pos=30: HTTP %d, want 200", status)
	}
	if got := qaAcctProgressSlots(t, db, ep2); len(got) != 1 || got[userID] != 30 {
		t.Fatalf("after plain PUT: ep2 progress slots = %v, want exactly {user %d:30}", got, userID)
	}
	qaAcctRequireSlots(t, "plain write (sub-threshold, no completion)", ep2, qaAcctWatchedSlots(t, db, ep2)) // want NONE

	// THE HIDDEN WRITE — invisible ≡ unknown on the write path: 404
	// not_found and NO row in ANY slot (visibleWhere gated the store call
	// before any upsert).
	if status := qaAcctPutProgress(t, j, bearer, epB, 10); status != http.StatusNotFound {
		t.Fatalf("session PUT on hidden-library item: HTTP %d, want 404", status)
	}
	if got := qaAcctProgressSlots(t, db, epB); len(got) != 0 {
		t.Fatalf("hidden-library PUT wrote rows: %v, want NO row in any slot", got)
	}
	qaAcctRequireSlots(t, "hidden write refused", epB, qaAcctWatchedSlots(t, db, epB)) // want NONE
}

// qaAcctLaw is ONE principal kind's expected posture over the matrix (the
// outcomes' source: the shipped accounts deltas — see the table builder).
type qaAcctLaw struct {
	name    string // the principal kind's row label
	token   string // the principal's bearer
	seeAll  bool   // true: hidden targets answer 200 (see-all law); false: 404 (hidden ≡ unknown)
	ownSlot bool   // true: progress reads pin the OWN slot's position; false: see-all multi-slot (position unspecified)
}

// qaAcctMatrixRow is one (principal, surface, target, want) cell. wantPos
// asserts the served position_seconds (−1: not specified by any delta for
// this cell — see the non-assertions note in the file header).
type qaAcctMatrixRow struct {
	principal string
	surface   string
	target    string
	path      string
	want      int
	wantPos   int64
	wantRel   string // item/series identity on 200s
	wantLib   int64  // library 200 identity
	wantItem  string // progress 200 item identity
}

// TestAccountsViewerThreadingMatrix is the l6-accounts 11.3 threading
// matrix: four principal kinds × four read surfaces × visible/hidden
// targets over ONE assertion engine. The laws:
//
//   - env-admin    → access.Admin(): sees all, reads across slots (the
//     slot-0 staged rows serve; role lifts grant scoping — "Admin-role user
//     sees everything", "Legacy principals keep see-all").
//   - session      → identity.ResolveViewer(uid): the grant union {A}
//     exactly; progress reads pin the OWN slot ("Continue rows follow the
//     viewer").
//   - bound device → rides its user's resolved Viewer EXACTLY (9.3 "Binding
//     re-scopes the device") — same law as the session, different credential
//     leg (the middleware's device-kind lookup stamped the bound UserID).
//   - unbound      → access.LegacyDevice(): see-all on a server WITH users
//     ("Legacy principals keep see-all"), reading across slots.
func TestAccountsViewerThreadingMatrix(t *testing.T) {
	if testing.Short() {
		t.Skip("QA accounts threading matrix: skips under -short (builds binaries + subprocesses)")
	}
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("QA accounts threading matrix needs %s on PATH (fixture generation + probing; INV4: optional binary): %v", bin, err)
		}
	}

	rootA := t.TempDir()
	qaAcctMedia(t, filepath.Join(rootA, qaAcctMatrixEpA))
	rootB := t.TempDir()
	qaAcctMedia(t, filepath.Join(rootB, qaAcctMatrixEpB))

	j := qaAcctStartJoint(t, qaAcctAdminMatrix, "QA Acct Matrix Alpha", "QA Acct Matrix Bravo", rootA, rootB)
	for _, lib := range []int64{j.libA, j.libB} {
		if res := scanLibrary(t, j.client, j.srv.baseURL, j.admin, lib); res.Discovered != res.Persisted {
			t.Fatalf("scan lib %d: discovered=%d persisted=%d; warnings=%v", lib, res.Discovered, res.Persisted, res.Warnings)
		}
	}
	qaSerialWaitSettled(t, j.client, j.srv.baseURL, j.admin, j.libA, j.libB)

	findByRel := func(lib int64, rel string) string {
		for _, it := range listItems(t, j.client, j.srv.baseURL, j.admin, lib) {
			if it.RelativePath == rel {
				return it.ID
			}
		}
		t.Fatalf("item %q missing from lib %d", rel, lib)
		return ""
	}
	itA := findByRel(j.libA, qaAcctMatrixEpA)
	itB := findByRel(j.libB, qaAcctMatrixEpB)
	srA, srB := "", ""
	for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.libA) {
		srA = sr.ID
	}
	for _, sr := range qaSerialListSeries(t, j.client, j.srv.baseURL, j.admin, j.libB) {
		srB = sr.ID
	}
	if itA == "" || itB == "" || srA == "" || srB == "" {
		t.Fatalf("fixture grounding failed: itA=%q itB=%q srA=%q srB=%q", itA, itB, srA, srB)
	}

	// The auth-chain substrate: ONE grouped user, ONE granting group (libA
	// only), the session login, and the two devices — one BOUND to the user
	// through the real 9.3 surface, one left UNBOUND (legacy see-all).
	userID := qaAcctCreateUser(t, j, qaAcctUsername)
	group := qaAcctCreateGroup(t, j, qaAcctGroupName)
	qaAcctAddMember(t, j, group, qaAcctUsername)
	qaAcctGrantCollection(t, j, group, j.libA)
	session := qaAcctLogin(t, j, qaAcctUsername)
	boundTok, boundCode := qaAcctPairDevice(t, j)
	unboundTok, _ := qaAcctPairDevice(t, j)
	qaAcctBindDevice(t, j, boundCode, userID)

	// Ledger staging (the slot discriminators): slot-0 rows on BOTH items
	// (7 / 11 — sub-threshold, no completions), the user's own row on itA
	// (3). itA now holds TWO slots — the own-slot principals must read 3.
	db := qaAcctOpenLedger(t, j)
	if status := qaAcctPutProgress(t, j, j.admin, itA, qaAcctPosA0); status != http.StatusOK {
		t.Fatalf("stage PUT itA slot0: HTTP %d, want 200", status)
	}
	if status := qaAcctPutProgress(t, j, j.admin, itB, qaAcctPosB0); status != http.StatusOK {
		t.Fatalf("stage PUT itB slot0: HTTP %d, want 200", status)
	}
	if status := qaAcctPutProgress(t, j, session, itA, qaAcctPosUser); status != http.StatusOK {
		t.Fatalf("stage PUT itA user slot: HTTP %d, want 200", status)
	}

	// THE TABLE — one assertion engine, rows = (principal, surface, target,
	// want), built from the four laws: 4 principals × 4 surfaces × 2
	// targets = 32 rows.
	pathLibA := j.srv.baseURL + "/api/v1/libraries/" + strconv.FormatInt(j.libA, 10)
	pathLibB := j.srv.baseURL + "/api/v1/libraries/" + strconv.FormatInt(j.libB, 10)
	laws := []qaAcctLaw{
		{name: "env_admin", token: j.admin, seeAll: true, ownSlot: false},
		{name: "session", token: session, seeAll: false, ownSlot: true},
		{name: "bound_device", token: boundTok, seeAll: false, ownSlot: true},
		{name: "unbound_device", token: unboundTok, seeAll: true, ownSlot: false},
	}
	tokens := map[string]string{}
	var rows []qaAcctMatrixRow
	for _, law := range laws {
		tokens[law.name] = law.token
		wantHidden := http.StatusOK
		if !law.seeAll {
			wantHidden = http.StatusNotFound
		}
		posA := int64(-1) // see-all over a two-slot item: position unspecified by any delta
		if law.ownSlot {
			posA = qaAcctPosUser
		}
		posB := int64(-1) // hidden target for scoped kinds: no 200 to read
		if law.seeAll {
			posB = qaAcctPosB0 // the single (slot-0) row — unambiguous
		}
		rows = append(rows,
			qaAcctMatrixRow{law.name, "library", "visible", pathLibA, http.StatusOK, -1, "", j.libA, ""},
			qaAcctMatrixRow{law.name, "library", "hidden", pathLibB, wantHidden, -1, "", j.libB, ""},
			qaAcctMatrixRow{law.name, "item", "visible", j.srv.baseURL + "/api/v1/items/" + itA, http.StatusOK, -1, qaAcctMatrixEpA, 0, ""},
			qaAcctMatrixRow{law.name, "item", "hidden", j.srv.baseURL + "/api/v1/items/" + itB, wantHidden, -1, qaAcctMatrixEpB, 0, ""},
			qaAcctMatrixRow{law.name, "series", "visible", j.srv.baseURL + "/api/v1/series/" + srA, http.StatusOK, -1, qaAcctMatrixDirA, 0, ""},
			qaAcctMatrixRow{law.name, "series", "hidden", j.srv.baseURL + "/api/v1/series/" + srB, wantHidden, -1, qaAcctMatrixDirB, 0, ""},
			qaAcctMatrixRow{law.name, "progress", "visible", j.srv.baseURL + "/api/v1/progress/" + itA, http.StatusOK, posA, "", 0, itA},
			qaAcctMatrixRow{law.name, "progress", "hidden", j.srv.baseURL + "/api/v1/progress/" + itB, wantHidden, posB, "", 0, itB},
		)
	}

	// THE ENGINE — every row: one GET, one decode, one assert path.
	for i, row := range rows {
		t.Run(fmt.Sprintf("%s/%s/%s", row.principal, row.surface, row.target), func(t *testing.T) {
			var got qaAcctAnyOrError
			status := doRequest(t, j.client, http.MethodGet, row.path, tokens[row.principal], nil, &got)
			if status != row.want {
				t.Fatalf("row %d (%s %s %s): HTTP %d, want %d", i, row.principal, row.surface, row.target, status, row.want)
			}
			if status == http.StatusNotFound {
				// hidden ≡ unknown: the canonical error body, never 403 or a
				// shape leak.
				if got.Error.Code != "not_found" {
					t.Fatalf("row %d (%s %s %s): error code = %q, want not_found", i, row.principal, row.surface, row.target, got.Error.Code)
				}
				return
			}
			switch row.surface {
			case "library":
				if got.ID != row.wantLib {
					t.Fatalf("row %d (%s library %s): served id = %d, want %d", i, row.principal, row.target, got.ID, row.wantLib)
				}
			case "item", "series":
				ent := got.Item
				if row.surface == "series" {
					ent = got.Series
				}
				if ent.ID == "" || ent.RelativePath != row.wantRel {
					t.Fatalf("row %d (%s %s %s): served {id:%q rel:%q}, want rel %q", i, row.principal, row.surface, row.target, ent.ID, ent.RelativePath, row.wantRel)
				}
			case "progress":
				if got.ItemID != row.wantItem {
					t.Fatalf("row %d (%s progress %s): served item %q, want %q", i, row.principal, row.target, got.ItemID, row.wantItem)
				}
				if row.wantPos >= 0 && got.PositionSeconds != row.wantPos {
					t.Fatalf("row %d (%s progress %s): served position %d, want %d", i, row.principal, row.target, got.PositionSeconds, row.wantPos)
				}
			}
		})
	}

	// THE SET BLOCK — the resolved SET per principal (one read each; the
	// grant-union, listing-slot, and slot-scoping laws on the LIST
	// surfaces).
	scoped := map[string]bool{"session": true, "bound_device": true}
	for _, name := range []string{"env_admin", "session", "bound_device", "unbound_device"} {
		t.Run("sets/"+name, func(t *testing.T) {
			token := tokens[name]
			// Library list: see-all kinds carry both libraries; scoped kinds
			// exactly the grant union {A}.
			gotLibs := qaAcctLibIDs(t, j, token)
			if scoped[name] {
				if len(gotLibs) != 1 || !gotLibs[j.libA] {
					t.Fatalf("%s library set = %v, want exactly {libA=%d}", name, gotLibs, j.libA)
				}
			} else if len(gotLibs) != 2 || !gotLibs[j.libA] || !gotLibs[j.libB] {
				t.Fatalf("%s library set = %v, want exactly {libA=%d libB=%d}", name, gotLibs, j.libA, j.libB)
			}
			// Listing slots on the hidden library: scoped kinds answer
			// 200-EMPTY (never 403, never a count) — items and series both.
			for _, surface := range []string{"items", "series"} {
				var list struct {
					Items []json.RawMessage `json:"items"`
				}
				url := j.srv.baseURL + "/api/v1/" + surface + "?library=" + strconv.FormatInt(j.libB, 10)
				if status := doRequest(t, j.client, http.MethodGet, url, token, nil, &list); status != http.StatusOK {
					t.Fatalf("GET %s of hidden lib: HTTP %d, want 200", surface, status)
				}
				if empty := len(list.Items) == 0; empty != scoped[name] {
					t.Fatalf("%s %s listing of hidden lib: %d rows, wantEmpty=%v", name, surface, len(list.Items), scoped[name])
				}
			}
			// The visible listing arm carries exactly the item for the
			// scoped kinds.
			var items struct {
				Items []itemDTO `json:"items"`
			}
			urlA := j.srv.baseURL + "/api/v1/items?library=" + strconv.FormatInt(j.libA, 10)
			if status := doRequest(t, j.client, http.MethodGet, urlA, token, nil, &items); status != http.StatusOK {
				t.Fatalf("GET items of visible lib: HTTP %d, want 200", status)
			}
			if scoped[name] {
				if len(items.Items) != 1 || items.Items[0].ID != itA {
					t.Fatalf("%s items of visible lib = %+v, want exactly [%s]", name, items.Items, itA)
				}
			}
			// Progress list: see-all kinds read across slots (the item SET
			// is both items); scoped kinds their own slot's rows (itA only).
			var prog struct {
				Items []struct {
					ItemID string `json:"item_id"`
				} `json:"items"`
			}
			if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/progress?limit=100", token, nil, &prog); status != http.StatusOK {
				t.Fatalf("GET /progress: HTTP %d, want 200", status)
			}
			seen := map[string]bool{}
			for _, r := range prog.Items {
				seen[r.ItemID] = true
			}
			if scoped[name] {
				if len(seen) != 1 || !seen[itA] {
					t.Fatalf("%s progress set = %v, want exactly {%s} (own slot only)", name, seen, itA)
				}
			} else if len(seen) != 2 || !seen[itA] || !seen[itB] {
				t.Fatalf("%s progress set = %v, want exactly {%s %s} (reads across slots)", name, seen, itA, itB)
			}
		})
	}

	// THE LIVE-VISIBILITY TAIL — the visibility CONJUNCT isolated: revoke
	// libA from the group while the user's OWN progress row on itA still
	// exists (proven by the direct read), so the 404 that follows can only
	// be the conjunct — not absence, not another user's row. Re-granting
	// restores the read (the floor is live, resolved per request).
	qaAcctRevokeCollection(t, j, group, j.libA)
	if got := qaAcctProgressSlots(t, db, itA); got[userID] != qaAcctPosUser {
		t.Fatalf("after revoke: itA user-slot rows = %v, want the row to SURVIVE the grant change", got)
	}
	for _, name := range []string{"session", "bound_device"} {
		var prog qaAcctAnyOrError
		if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/progress/"+itA, tokens[name], nil, &prog); status != http.StatusNotFound {
			t.Fatalf("%s progress after revoke: HTTP %d, want 404 (own row exists — direct read proved it — invisible ≡ unknown)", name, status)
		}
		var libs struct {
			Items []json.RawMessage `json:"items"`
		}
		if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/libraries", tokens[name], nil, &libs); status != http.StatusOK || len(libs.Items) != 0 {
			t.Fatalf("%s libraries after revoke: HTTP %d, %d rows, want 200 empty (the empty grant resolves fail-closed)", name, status, len(libs.Items))
		}
	}
	// The role/legacy laws are UNAFFECTED by grants: admin and the unbound
	// device keep seeing both libraries.
	for _, name := range []string{"env_admin", "unbound_device"} {
		gotLibs := qaAcctLibIDs(t, j, tokens[name])
		if len(gotLibs) != 2 || !gotLibs[j.libA] || !gotLibs[j.libB] {
			t.Fatalf("%s libraries after revoke = %v, want both (grant scoping never applies to this principal kind)", name, gotLibs)
		}
	}
	qaAcctGrantCollection(t, j, group, j.libA)
	var prog qaAcctAnyOrError
	if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/progress/"+itA, session, nil, &prog); status != http.StatusOK || prog.PositionSeconds != qaAcctPosUser {
		t.Fatalf("session progress after re-grant: HTTP %d pos %d, want 200 pos %d (the floor is live)", status, prog.PositionSeconds, qaAcctPosUser)
	}
}
